INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('68806578-2a16-4618-8643-c1582dc54d3b', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'De acordo com o art. 24 da Constituição Federal de 1988, compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Ivorá - RS / Instrutor de Música / Questão: 28', 'O art. 24, I, CF/88 estabelece expressamente a competência concorrente da União, dos Estados e do DF para legislar sobre direito tributário, financeiro, penitenciário, econômico e urbanístico. As demais alternativas tratam de matérias de competência privativa da União (art. 22): civil, comercial e penal (inciso I); desapropriação (inciso II); nacionalidade, cidadania e naturalização (inciso XIII); seguridade social (inciso XXIII). Na competência concorrente, a União fixa normas gerais e os Estados legislam de forma suplementar (art. 24, §§1º e 2º).', 1, true),
('e5d1c46f-a8cb-44a9-8224-0e7521ea09c4', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'Conforme a CF, manter o serviço postal é responsabilidade de qual ente público?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Estância Velha - RS / Pintor de Sinalização / Questão: 33', 'O art. 21, X, CF/88 estabelece competência exclusiva da União para manter o serviço postal e o correio aéreo nacional, exercida pela ECT. O STF (ADPF 46) reconheceu o regime de exclusividade estatal para os serviços postais.', 2, true),
('3ef89002-d726-4a23-900d-c814aeb127b6', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'Conforme a CF, compete privativamente à União legislar sobre:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Câmara de Venâncio Aires - RS / Contador / Questão: 24', 'O art. 22, XXII, CF/88 estabelece que compete privativamente à União legislar sobre competência da polícia federal e das polícias rodoviária e ferroviária federais. As demais alternativas dizem respeito a matérias de competência concorrente (art. 24, incisos XV, IX, I) ou comum (proteção ao patrimônio histórico e cultural — art. 23, III e IV), não privativas.', 3, true),
('df1ae47d-2ce1-4fa2-a8ae-349b6899236d', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'Nos termos da CF/88, são bens da União, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Conselho Regional de Medicina do Rio Grande do Sul CREMERS - RS / Assistente Administrativo / Questão: 20', 'A alternativa que não corresponde a bem da União é a D: propriedade privada, por definição, pertence a particulares, não se enquadrando no rol do art. 20, CF/88. As demais alternativas correspondem a incisos expressos do art. 20: mar territorial (VI), potenciais de energia hidráulica (VIII), recursos minerais (IX) e terras tradicionalmente ocupadas pelos índios (XI).', 4, true),
('994620d2-acf2-4686-bb02-37fce42c221a', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'Conforme a CF/88, NÃO é uma competência privativa da União legislar sobre:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Ibirapuitã - RS / Procurador do Município / Questão: 20', 'A alternativa C não é competência privativa da União: florestas, caça, pesca, fauna e proteção do meio ambiente são matérias de competência concorrente (art. 24, VI). Vale notar que "manter o serviço postal" é competência exclusiva administrativa (art. 21, X), mas legislar sobre o tema situa-se no art. 22 (não expresso diretamente, mas correlato a serviços da União); de todo modo, as demais alternativas — populações indígenas (art. 22, XIV), atividades nucleares de qualquer natureza (art. 22, XXVI) e comércio exterior e interestadual (art. 22, VIII) — são efetivamente matérias de competência privativa da União, o que reforça que apenas a alternativa C está fora desse rol.', 5, true),
('8b6432c1-2792-49ee-8895-08e71ccecbc8', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'Segundo o Art. 24 da CF/88, NÃO compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Instituto Federal Catarinense IFC - BR / Tecnólogo - Área:Processos Escolares / Questão: 45', 'A alternativa que NÃO é competência concorrente é a B: diretrizes e bases da educação nacional são matéria de competência privativa da União (art. 22, XXIV), e não concorrente. As demais alternativas — educação, cultura, desporto, ensino, pesquisa, desenvolvimento e inovação — estão previstas no art. 24, IX, como competência concorrente entre União, Estados e DF. A alternativa E (nacionalidade, cidadania e naturalização) é matéria de competência privativa da União (art. 22, XIII), reforçando que tanto B quanto E poderiam ser consideradas corretas para a pergunta, mas o gabarito oficial da banca apontou a alternativa B.', 6, true),
('6acc34d7-b172-47ac-99b1-aa5b8ab5fe27', '209ba7f1-0766-4622-a7ca-e096c5a9a559', 'De acordo com a CF, é competência comum da União, dos Estados, do Distrito Federal e dos Municípios:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2021 / Prefeitura de Ivoti - RS / Agente Técnico Fazendário / Questão: 18', 'O art. 23, V, CF/88 estabelece como competência comum proporcionar os meios de acesso à cultura, à educação, à ciência, à tecnologia, à pesquisa e à inovação. As demais alternativas descrevem competências exclusivas da União (art. 21, III, II, VI e X, respectivamente), incompatíveis com a natureza cooperativa das competências comuns.', 7, true);
